    active_link = ephemeral_graph.lookup(blinded_id, max_ttl="48h")
    if not active_link:
        # Clean rooms only confirm existing overlaps, so accept unlinked status instead of guessing
        return register_isolated_frequency_cap(blinded_id)

    # 4. Push frequency and suppression states, never raw identities, across boundaries
    return sync_aggregate_caps(active_link.cluster_id)
